                    return `<i tabindex="0" role="img" class="${isCurrent ? "is-current" : ""}" style="height:${heightFor(value)}px;background:${isCurrent ? barRamp[tone][7] : barRamp[tone][2]}" data-tooltip="${barLabel}" aria-label="${barLabel}"></i>`;
